const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let local=false, jobs=[], imported=[], currentView='overview', lastJobs='';
const labels={play_verified:'实玩已验证',tutorial_stated:'引导说明',user_reported:'用户经验',hypothesis:'待验证'};
const phases={starting:'正在打开浏览器',awaiting_user:'等待你完成登录与旅程准备',playing:'自动游玩中',evaluating:'生成评审报告',done:'运行结束',failed:'运行未完成',cancelled:'已停止'};
const statuses={completed:'观察到结局',step_limit:'达到步骤上限',stalled:'等待超时，已停止',failed:'执行失败',running:'游玩中'};
const [knowledge,tutorial,story]=await Promise.all(['framework','tutorial','story'].map(x=>fetch(`/data/${x}.json`).then(r=>r.json())));
$('#rule-count').textContent=knowledge.rules.length;$('#knowledge-count').textContent=String(knowledge.rules.length).padStart(2,'0');$('#topic-count').innerHTML=`${tutorial.entries.length}<em>条</em>`;
function view(name){currentView=name;document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==name);document.querySelectorAll('nav button').forEach(el=>el.classList.toggle('active',el.dataset.view===name));$('#crumb').textContent=$(`nav button[data-view="${name}"] span`).textContent;history.replaceState(null,'',`#${name}`);}
document.querySelectorAll('[data-view],[data-goto]').forEach(el=>el.onclick=()=>view(el.dataset.view||el.dataset.goto));
$('.brand').onclick=()=>view('overview');
if(['overview','knowledge','guide','runs'].includes(location.hash.slice(1)))view(location.hash.slice(1));
function renderRules(){const text=$('#search').value.toLowerCase(),status=$('#filter').value;const all=knowledge.rules.filter(r=>(!status||r.status===status)&&`${r.rule} ${r.id}`.toLowerCase().includes(text));$('#rules').innerHTML=all.length?all.map(r=>`<article class="rule-card"><span class="pill ${r.status==='play_verified'?'green':r.status==='hypothesis'?'warm':''}">${labels[r.status]}</span><p>${esc(r.rule)}</p><small>来源：${esc(r.source)}</small></article>`).join(''):'<p>没有匹配的知识。</p>';}
$('#search').oninput=renderRules;$('#filter').onchange=renderRules;renderRules();
$('#tutorials').innerHTML=tutorial.entries.map(t=>`<details><summary>${esc(t.title)}</summary><p>${esc(t.text)}</p>${t.note?`<small>${esc(t.note)}</small>`:''}</details>`).join('');
$('#story-notes').innerHTML=`<span class="pill">${esc(story.status)}</span><h3 class="spaced">已知线索</h3><ul>${story.knownFacts.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><h3 class="spaced">待验证的问题</h3><ul>${story.questions.map(f=>`<li>${esc(f)}</li>`).join('')}</ul>`;
const steps=[['完成访问与登录','程序打开游戏浏览器；由你输入访问密码，完成账号登录与许可确认。App 不收集游戏密码。'],['从工作台创建新游戏','正式评测一律选择新游戏，禁止继续旧存档。覆盖或删除具体旧存档须确认；核验初始章节、任务和资源。手册版本0.2.4，报告记录引擎与剧本版本。'],['逐格阅读序章','鬼故事左下角点击揭示下一格；最后点击开始行动，再点击章节页继续旅程。程序记录各阶段文字和截图。'],['从引导学习玩法','通读卡牌说明、精力、压力与检定规则，区分引导说明、实玩验证、用户经验和猜测。'],['选择、执行、核对结果','AI 玩家读取知识、当前目标和已观察历史，给出简短依据与预期；点击后等正式结算再核对反馈。流程验证模式仅使用可复现的选项策略。'],['分开记录框架与故事','故事看叙事、人物和选择；框架看画面、交互、可靠性。在线失败时记录降级，换快模型重试的经验需要继续验证。'],['输出证据并更新知识','保存过程、截图、行动依据和报告。缺少模型或证据时不评分；新发现带上来源与验证范围。']];
$('#guide-steps').innerHTML=steps.map(([title,body],i)=>`<article class="guide-step"><b>0${i+1}</b><div><h3>${title}</h3><p>${body}</p></div></article>`).join('');
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,6000);}
async function post(path,body={}){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(data.error||'操作失败');return data;}
$('#new-run').onclick=()=>{$('#mode-note').textContent=local?'本地执行器已连接。启动后会打开独立的游戏浏览器。':'云端工作台已就绪。自动游玩需要在本机运行执行器；这里可直接浏览知识库、测试流程或导入游玩记录。';$('#local-command').hidden=local;$('#launch').disabled=!local;$('#start-dialog').showModal();};
$('#launch').onclick=async()=>{const button=$('#launch');button.disabled=true;$('#start-error').textContent='';try{await post('/api/jobs',{config:$('#target').value,strategy:$('#strategy').value});$('#start-dialog').close();view('runs');await refresh();}catch(e){$('#start-error').textContent=e.message;}finally{button.disabled=!local;}};
function renderJobs(){const all=[...jobs,...imported];$('#rated-count').textContent=String(all.filter(j=>j.evaluation?.status==='evaluated').length).padStart(2,'0');$('#jobs').innerHTML=all.length?all.slice().reverse().map(j=>{
 const r=j.run,e=j.evaluation;
 return `<article class="job" data-id="${esc(j.id)}"><div class="job-top"><h2>${esc(j.name)}</h2><span class="pill">${esc(phases[j.phase]||j.phase)}</span></div><p>${r?`${r.observations.length} 个观察状态 · ${r.actions.length} 次操作 · ${esc(statuses[r.status]||r.status)}`:'正在准备浏览器'}</p>
 ${j.phase==='awaiting_user'?`<div class="callout"><span>↗</span><p>请在已打开的游戏浏览器中完成密码、账号登录，创建全新测试旅程后回来，禁止继续旧存档。可以停在开场漫画。<br><label><input type="checkbox" class="save-session"> 在本机保存登录状态，便于下次复用</label></p></div><div class="job-actions"><button class="primary" data-action="ready">已准备好，开始自动游玩</button></div>`:''}
 ${!j.imported&&!['done','failed','cancelled'].includes(j.phase)?'<button class="secondary" data-action="stop">停止任务</button>':''}
 ${e?`<h3 class="spaced">评审结果</h3>${e.status==='evaluated'?`<div class="score-grid"><div>故事评分<strong>${esc(e.groups?.story?.score??'证据不足')}</strong><small>0–100 分 · 仅当前路线</small></div><div>框架评分<strong>${esc(e.groups?.framework?.score??'证据不足')}</strong><small>0–100 分 · 仅当前运行</small></div></div><p>${esc(e.summary)}</p>${e.dimensions.map(d=>`<details><summary>${esc(d.name)} · ${esc(d.score??'证据不足')}</summary><p>${esc(d.reason)}</p><small>证据：${esc(d.evidence.join(', '))}</small></details>`).join('')}`:`<div class="callout"><p>尚未评分 · ${esc(e.reason)}。原始游玩证据已保存。</p></div>`}`:''}
 ${!j.imported&&['done','failed'].includes(j.phase)&&r?.observations.length?'<div class="job-actions"><button class="secondary" data-action="evaluate">重新文字评审</button><button class="secondary" data-action="visual">评审文字与截图</button></div><p class="hint">评审将把本次游玩材料发送到本地 .env 配置的模型接口。</p>':''}
 ${j.error?`<p role="alert">${esc(j.error)}</p>`:''}
 ${r?`<details><summary>展开游玩证据与行动记录</summary><div class="timeline">${r.observations.map(o=>{const a=r.actions.find(x=>x.observation===o.id);return `<div class="event"><h3>${esc(o.id)} · ${esc(o.phase)}</h3><p>${esc(o.story)}</p>${a?`<p><strong>操作：</strong>${esc(a.text)}<br><strong>依据：</strong>${esc(a.reason||'界面流程推进')}<br><strong>预期：</strong>${esc(a.expected||'进入下一阶段')}</p>`:''}${!j.imported?`<img loading="lazy" src="/api/evidence/${esc(j.id)}/${esc(o.screenshot)}" alt="${esc(o.id)} 页面证据">`:'<p class="hint">此导入仅包含文字记录，截图保存在原始运行目录。</p>'}</div>`}).join('')}</div></details>`:''}</article>`;
 }).join(''):`<div class="empty"><div class="icon">◷</div><h2>让判断从一次真实游玩开始</h2><p>还没有自动执行的任务。手动探索知识已收录在知识库中。<br>在本地启动一次示例，或导入已有的 run.json。</p><button class="secondary" id="empty-start">开始一次游玩</button></div>`;
 const empty=$('#empty-start');if(empty)empty.onclick=()=>$('#new-run').click();
 $('#jobs').querySelectorAll('[data-action]').forEach(button=>button.onclick=async()=>{const card=button.closest('[data-id]'),id=card.dataset.id,action=button.dataset.action;button.disabled=true;try{await post(`/api/jobs/${id}/${['visual','evaluate'].includes(action)?'evaluate':action}`,{saveSession:card.querySelector('.save-session')?.checked===true,visual:action==='visual'});await refresh();}catch(e){toast(e.message);button.disabled=false;}});
}
$('#import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5_000_000)throw Error('请导入5MB以内的游玩记录');const data=JSON.parse(await file.text());if(!Array.isArray(data.observations)||!Array.isArray(data.actions)||typeof data.name!=='string'||data.observations.some(o=>typeof o.id!=='string'||typeof o.story!=='string'))throw Error('请选择有效的 DokiPlayer run.json');imported.push({id:`import-${Date.now()}`,name:data.name,phase:'已导入记录',run:data,imported:true});renderJobs();toast('记录已在当前浏览器读取');}catch(err){toast(err.message);}e.target.value='';};
async function refresh(){if(!local)return;try{const r=await fetch('/api/jobs');const next=await r.json(),str=JSON.stringify(next);if(str!==lastJobs){jobs=next;lastJobs=str;renderJobs();}}catch{toast('本地执行器连接已断开');}}
try{const r=await fetch('/api/status');if(r.ok&&r.headers.get('content-type')?.includes('application/json'))local=(await r.json()).local===true;}catch{}
$('#connection').textContent=local?'● 本地执行器已连接':'○ 云端知识库 · 执行器未连接';renderJobs();await refresh();if(local)setInterval(refresh,1800);
